k, amount = map(int, input().split())
coins = list(map(int, input().split()))
dist = {0: 0}
q = deque([0])
while q:
    cur = q.popleft()
    if cur == amount:
        break
    for c in coins:
        nxt = cur + c
        if nxt <= amount and nxt not in dist:
            dist[nxt] = dist[cur] + 1
            q.append(nxt)
